package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser#nextFieldName.
 * Designed to maximize branch and line coverage by simulating various JSON structures.
 */
public class ReaderBasedJsonParser_nextFieldName_TriageGen0Test {

    private ReaderBasedJsonParser createParser(String json) throws IOException {
        // Using StringReader to provide the input source
        return new ReaderBasedJsonParser(
                new IOContext(),
                0,
                new StringReader(json),
                null,
                null,
                null,
                0,
                0,
                false
        );
    }

    @Test
    public void testNextFieldName_SimpleObject() throws IOException {
        String json = "{\"key\":\"value\"}";
        ReaderBasedJsonParser parser = createParser(json);

        // First call to move to START_OBJECT
        Assert.assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        // nextFieldName should return "key"
        String fieldName = parser.nextFieldName();
        Assert.assertEquals("key", fieldName);

        // The next token should be the value
        Assert.assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
    }

    @Test
    public void testNextFieldName_EndOfObject() throws IOException {
        String json = "{\"a\":1}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextFieldName(); // "a"
        parser.nextToken(); // 1

        // After value, next field name in an empty-ish context should return null and move to END_OBJECT
        String fieldName = parser.nextFieldName();
        Assert.assertNull(fieldName);
        Assert.assertEquals(JsonToken.END_OBJECT, parser.nextToken());
    }

    @Test
    public void testNextFieldName_MultipleFieldsWithComma() throws IOException {
        String json = "{\"f1\":true,\"f2\":false}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT

        Assert.assertEquals("f1", parser.nextFieldName());
        Assert.assertEquals(JsonToken.VALUE_TRUE, parser.nextToken());

        Assert.assertEquals("f2", parser.nextFieldName());
        Assert.assertEquals(JsonToken.VALUE_FALSE, parser.nextToken());
    }

    @Test
    public void testNextFieldName_NullValue() throws IOException {
        String json = "{\"key\":null}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        Assert.assertEquals("key", parser.nextFieldName());
        Assert.assertEquals(JsonToken.VALUE_NULL, parser.nextToken());
    }

    @Test
    public void testNextFieldName_NumberValues() throws IOException {
        String json = "{\"pos\":123,\"neg\":-456}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT

        Assert.assertEquals("pos", parser.nextFieldName());
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());

        Assert.assertEquals("neg", parser.nextFieldName());
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
    }

    @Test
    public void testNextFieldName_ComplexValues() throws IOException {
        String json = "{\"arr\":[],\"obj\":{}}";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT

        Assert.assertEquals("arr", parser.nextFieldName());
        Assert.assertEquals(JsonToken.START_ARRAY, parser.nextToken());

        Assert.assertEquals("obj", parser.nextFieldName());
        Assert.assertEquals(JsonToken.START_OBJECT, parser.nextToken());
    }

    @Test
    public void testNextFieldName_IncompleteTokenHandling() throws IOException {
        // This tests the _tokenIncomplete logic if the parser state is manipulated or 
        // if a string is left hanging (though usually handled by nextToken)
        String json = "{\"key\":\"\"}";
        ReaderBasedJsonParser parser = createParser(json);
        parser.nextToken();
        Assert.assertEquals("key", parser.nextFieldName());
        Assert.assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
    }

    @Test
    public void testNextFieldName_EndArrayContext() throws IOException {
        // Testing the logic where i == INT_RBRACKET
        // This triggers the branch: if (i == INT_RBRACKET)
        String json = "[{\"a\":1}]";
        ReaderBasedJsonParser parser = createParser(json);

        parser.nextToken(); // START_ARRAY
        parser.nextToken(); // START_OBJECT
        parser.nextFieldName(); // "a"
        parser.nextToken(); // 1

        // Now at end of object, next field name should return null and set token to END_OBJECT
        // But we are inside an array. The code handles context switching.
        // To hit the INT_RBRACKET branch directly via nextFieldName, we need to be in a state
        // where nextFieldName is called and it sees a ']'

        // Note: The provided code logic for INT_RBRACKET/INT_RCURLY is specific to how 
        // the parser advances.
    }

    @Test(expected = IOException.class)
    public void testNextFieldName_MismatchedEndMarker() throws IOException {
        // Testing _reportMismatchedEndMarker
        // If we are in an Array context but find a '}'
        String json = "[}]";
        ReaderBasedJsonParser parser = createParser(json);
        parser.nextToken(); // START_ARRAY
        parser.nextFieldName(); // This will likely trigger error because '}' is not a valid field name start
    }

    @Test
    public void testNextFieldName_EOF() throws IOException {
        String json = "{}";
        ReaderBasedJsonParser parser = createParser(json);
        parser.nextToken(); // START_OBJECT
        parser.nextFieldName(); // returns null, token becomes END_OBJECT
        parser.nextToken(); // END_OBJECT

        // Now at EOF
        String result = parser.nextFieldName();
        Assert.assertNull(result);
    }

    @Test
    public void testNextFieldName_CurrentTokenIsFieldName() throws IOException {
        // Tests the first if block: if (_currToken == JsonToken.FIELD_NAME)
        String json = "{\"a\":1}";
        ReaderBasedJsonParser parser = createParser(json);
        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "a"

        // If we call nextFieldName while _currToken is already FIELD_NAME
        String result = parser.nextFieldName();
        Assert.assertNull(result);
    }
}
